properties.Script_1:
// Cambiar en la rejilla el elemento seleccionado al anterior o siguiente campo editable

// Leemos el registro al que nos movemos
var idNuevo = theRoot.varToInt("TXT_ID_BUS");
var registroNuevo = new VRegister(theRoot);
registroNuevo.setTable("sygemat_corralon_dat/FIC_REG_W");
registroNuevo.readRegister("ID", [idNuevo], VRegister.SearchThis);

if (registroNuevo)
{
	// Nos posicionamos en la rejilla del multivista y seleccionamos el registro a editar
    var formulario = theRoot.dataView();
	var rejilla = formulario.control("LST_REG");
    rejilla.setCurrentSelect(registroNuevo);
};
